import{z as E,x as d,o as A,c as i,q as r,j as t,D as e,d as o,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"ARM 对 RISC-V","description":"","frontmatter":{"title":"ARM 对 RISC-V","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arm-vs-riscv.md","filePath":"cs/arm-vs-riscv.md","lastUpdated":1791063341000}'),C={name:"cs/arm-vs-riscv.md"};function R(c,a,S,p,I,B){const s=d("Mermaid");return A(),i("div",null,[a[2]||(a[2]=r('<h1 id="arm-对-risc-v" tabindex="-1">ARM 对 RISC-V <a class="header-anchor" href="#arm-对-risc-v" aria-label="Permalink to &quot;ARM 对 RISC-V&quot;">​</a></h1><div class="epigraph"><p>两者都是定长 load/store RISC；差别在条件码、压缩、向量、特权命名与授权模式，而不是「一个 RISC 一个不是」。</p><footer>—— 据 ARM Architecture Reference Manual；The RISC-V Instruction Set Manual；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/aarch64-isa">上一课</a>钉了 A64。<a href="/cs/riscv-int-isa">RISC-V 整数</a> 已是本栏主干。缺口是<strong>对照表</strong>：避免后课原子、fence、页表各说各话时读者以为在学第三种哲学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>相同：运算在寄存器、访存单独、定长基础指令、特权与用户分离。不同：ARM 用 NZCV 与条件分支编码；RISC-V 比较结果进通用寄存器再分支。ARM 商业授权核；RISC-V 开放 ISA、核多家。压缩：ARM 有历史 Thumb，A64 不定长；RISC-V <code>C</code> 扩展 16 位混长（后课）。向量：ARM SVE 与 RISC-V RVV 都是可变长，后课分讲。缺口不是再介绍 A64 寄存器，而是这些<strong>选择的组成后果</strong>。</p><p><span class="marginnote">术语翻译：NZCV 是 ARM 的四个标志位——负（N）、零（Z）、进位（C）、溢出（V）。运算指令顺手把它们置好，紧随其后的条件分支只看标志决定跳不跳；RISC-V 没有这组位，比较结果当普通数字写进通用寄存器，分支再用它。</span></p><p>页表：ARM 多级与 ASIDs；RISC-V Sv39 后课。虚拟化：ARM EL2 vs RISC-V H 扩展。</p><h3 id="对照不是「谁更快」" tabindex="-1">对照不是「谁更快」 <a class="header-anchor" href="#对照不是「谁更快」" aria-label="Permalink to &quot;对照不是「谁更快」&quot;">​</a></h3><p>性能是微结构、工艺、<a href="/cs/dennard-power-wall">功耗墙</a> 与编译器。ISA 对照课不宣布基准冠军。把课写成选购指南，会滑出系统栈。</p><p><span class="marginnote">两份官方手册 + CA:AQA 的 RISC 章节。本课用差异点列表，不抄指令全表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列一张心智表：寄存器数、零寄存器、链接寄存器（<code>x30</code> vs <code>ra</code>）、栈指针是否特殊、系统调用指令（<code>svc</code> vs <code>ecall</code>）、内存模型（ARM 弱、RISC-V 弱，fence 课）。ABI：AAPCS64 vs RISC-V psABI，最后一课收。</p>',12)),(A(),t(l,null,{default:e(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMM%5B%22%E5%AE%9A%E9%95%BF%20load%2Fstore%22%5D%20--%3E%20ARM%5B%22NZCV%20%2F%20EL%20%2F%20GIC%22%5D%0A%20%20COMM%20--%3E%20RV%5B%22GPR%20%E6%AF%94%E8%BE%83%20%2F%20%E7%89%B9%E6%9D%83%20CSR%20%2F%20PLIC%22%5D%0A%20%20ARM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8E%9F%E5%AD%90%20LR%2FSC%20%E4%B8%8E%20CAS%22%5D%0A%20%20RV%20--%3E%20LATER%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>教学 CPU：RISC-V 更易画单周期；ARM 教材同样可画，字段不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>原子：ARM 有 <code>ldxr/stxr</code> 与后来的 LSE <code>cas</code>；RISC-V <code>A</code> 扩展 LR/SC 与 AMO。下一课专讲。SIMD 再下一组。本课防止「ARM=CISC」的谣言（那是 x86）。</p><p><span class="marginnote">常见误区：初学者常把「指令多、扩展多」当成 CISC。ARM 与 RISC-V 都是定长 load/store 的 RISC；真正变长 CISC 外壳的是 x86——指令 1 到 15 字节不等，译码要做拆分。那是第三位主角，别把它的特征记到本课两位头上。</span></p><p><span class="marginnote">直觉类比：LR/SC 像动货架前先挂「我在整理」的牌子，回来结账时牌子还在才能放下；期间任何别的手碰过货架，牌子就掉（SC 失败），整段重来。多核争用时可能连败几次，这是 LR/SC 与 ldxr/stxr 共同的赌注。</span></p>',5)),(A(),t(l,null,{default:e(()=>[n(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20INC%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E5%8E%9F%E5%AD%90%E5%8A%A0%E4%B8%80%22%5D%20--%3E%20LDXR%5B%22ARM%3A%20ldxr%20%E7%8B%AC%E5%8D%A0%E8%AF%BB%22%5D%0A%20%20LDXR%20--%3E%20ADD%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%8A%A0%E4%B8%80%22%5D%0A%20%20ADD%20--%3E%20STXR%5B%22stxr%20%E7%8B%AC%E5%8D%A0%E5%86%99%2C%20%E8%A2%AB%E4%BA%BA%E6%8F%92%E6%89%8B%E5%88%99%E9%87%8D%E6%9D%A5%22%5D%0A%20%20INC%20--%3E%20LR%5B%22RISC-V%3A%20LR%20%E7%8B%AC%E5%8D%A0%E8%AF%BB%22%5D%0A%20%20LR%20--%3E%20ADD2%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%8A%A0%E4%B8%80%22%5D%0A%20%20ADD2%20--%3E%20SC%5B%22SC%20%E6%9D%A1%E4%BB%B6%E5%AD%98%2C%20%E8%A2%AB%E4%BA%BA%E6%8F%92%E6%89%8B%E5%88%99%E9%87%8D%E6%9D%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较授权费，不预测生态。不把 MIPS/POWER 拉进来冲淡。不写 DSP 定点指令全集。</p><p>后课默认：ARM 与 RISC-V 同属 RISC 家族；差异在条件码、压缩、特权与扩展哲学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>都是定长 load/store；x86 才是变长 CISC 外壳。</li><li>条件码 vs 比较进寄存器；特权命名不同。</li><li>速度不由本课裁定。</li><li>出处：ARM ARM；RISC-V ISA Manual；Hennessy and Patterson, CA:AQA。</li></ul>',5))])}const V=E(C,[["render",R]]);export{h as __pageData,V as default};
